func coerceDefaultInt32IfInRange(val any) (any, bool) {
	switch v := val.(type) {
	case int32:
		return v, true
	case int:
		if v >= math.MinInt32 && v <= math.MaxInt32 {
			return int32(v), true
		}
	case int64:
		if v >= math.MinInt32 && v <= math.MaxInt32 {
			return int32(v), true
		}
	case json.Number:
		if i, err := v.Int64(); err == nil && i >= math.MinInt32 && i <= math.MaxInt32 {
			return int32(i), true
		}
	}
	return val, false
}

